function example() {
  const [value, setValue] = useState(20);
  return (
    <>
      <RingProgress value={value} label="Upload" color="success" mb="3">
        {value}%
      </RingProgress>
      <Paragraph role="status">
        {value >= 100 ? 'Upload complete' : ''}
      </Paragraph>
      <Button size="small" onClick={() => setValue(v => Math.min(100, v + 20))}>
        Move it on
      </Button>
    </>
  );
}
